const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Lago Hermoso, Argentina coordinates (approximate center)
  const lagoHermoso = ee.Geometry.Point([-71.28, -40.85]);
  const region = lagoHermoso.buffer(5000); // 5km buffer for analysis

  // Date 1: March 29, 1987 (morning)
  const date1Start = '1987-03-29';
  const date1End = '1987-03-30';

  // Date 2: February 15, 2001
  const date2Start = '2001-02-15';
  const date2End = '2001-02-16';

  // Function to calculate cloud percentage from Landsat
  function calculateCloudPercentage(image, geometry) {
    const cloudBit = 1 << 5; // Cloud bit in pixel_qa
    const cloudShadowBit = 1 << 3; // Cloud shadow bit

    const qa = image.select('pixel_qa');
    const clouds = qa.bitwiseAnd(cloudBit).neq(0);

    const total = ee.Image.constant(1);
    const stats = total.addBands(clouds).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 30,
      maxPixels: 1e9
    });

    return stats;
  }

  // Try Landsat 5 for 1987
  let col1987 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(lagoHermoso)
    .filterDate(date1Start, date1End);

  const size1987 = col1987.size().getInfo();
  console.log(`1987 Images found: ${size1987}`);

  if (size1987 === 0) {
    // Try Landsat 4
    col1987 = ee.ImageCollection('LANDSAT/LT04/C01/T1_SR')
      .filterBounds(lagoHermoso)
      .filterDate(date1Start, date1End);
    const size1987_L4 = col1987.size().getInfo();
    console.log(`1987 Landsat 4 Images found: ${size1987_L4}`);

    if (size1987_L4 === 0) {
      console.log('No images for March 29, 1987');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Try Landsat 7 for 2001
  let col2001 = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR')
    .filterBounds(lagoHermoso)
    .filterDate(date2Start, date2End);

  const size2001 = col2001.size().getInfo();
  console.log(`2001 Images found: ${size2001}`);

  if (size2001 === 0) {
    console.log('No images for February 15, 2001');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get first image from each collection
  const img1987 = ee.Image(col1987.first());
  const img2001 = ee.Image(col2001.first());

  // Calculate cloud percentages
  const stats1987 = calculateCloudPercentage(img1987, region);
  const stats2001 = calculateCloudPercentage(img2001, region);

  const total1987 = stats1987.get('constant').getInfo();
  const clouds1987 = stats1987.get('pixel_qa').getInfo();
  const total2001 = stats2001.get('constant').getInfo();
  const clouds2001 = stats2001.get('pixel_qa').getInfo();

  if (total1987 === null || clouds1987 === null || total2001 === null || clouds2001 === null) {
    console.log('Calculation failure');
    console.log('<answer>C3</answer>');
    return;
  }

  const cloudPct1987 = (clouds1987 / total1987) * 100;
  const cloudPct2001 = (clouds2001 / total2001) * 100;

  console.log(`1987 Cloud Cover: ${cloudPct1987.toFixed(2)}% (${clouds1987}/${total1987} pixels)`);
  console.log(`2001 Cloud Cover: ${cloudPct2001.toFixed(2)}% (${clouds2001}/${total2001} pixels)`);

  if (cloudPct1987 > cloudPct2001) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
